def _fix_pt(value):
    if isinstance(value, str):
        def word(match):
            original = match.group(0)
            result = _PT_WORDS.get(original.lower(), original)
            return result[:1].upper() + result[1:] if original[:1].isupper() else result
        value = _re.sub(r"\b[A-Za-z]+\b", word, value)
        value = _re.sub(r"\bnao e\b", "n\u00e3o \u00e9", value, flags=_re.I)
        value = _re.sub(r"\be (?=(?:um|uma|o|a|restrito|proibida|desconhecida|diagn\u00f3stico|incerto|importante|aprovada|distinto|proposto|capaz|medida|necessario|possivel|avaliada|proibido)\b)", "\u00e9 ", value, flags=_re.I)
        if value.startswith("E "):
            value = "\u00c9 " + value[2:]
        return value
    if isinstance(value, list):
        return [_fix_pt(item) for item in value]
    if isinstance(value, dict):
        return {key: _fix_pt(item) for key, item in value.items()}
    return value

